from robot.utils import timestr_to_secs
from ..filecollector.filecollector import FileCollector
from ute_common_store.store import Store
from ute_common_interface.scope import ScopeController
import logging


class BaseInterface(ScopeController):

    def __init__(self):
        super(BaseInterface, self).__init__()
        self.command_store = Store()
        self._log = logging.getLogger(__name__)

    def _convert_to_secs(self, provided_time):
        """Coverts provided time to seconds."""
        return provided_time if provided_time is None else int(timestr_to_secs(provided_time))
